off_patch:
def d(n):
	while len(str(n))!=1:
		n = sum(int(d) for d in str(n))
	return n

n_1 = int(input())
q, r = divmod(n_1, 9)
d = [q] + [q + 1] * r + [q] * (8 - r)
res = 0
for i in range(9):
    for j in range(9):
        res += d[i] * d[j] * d[i * j % 9]
for i in range(1, n_1 + 1):
    res -= n_1 // i
print(res)

